let lang=document.documentElement.lang in D?document.documentElement.lang:'ko';let page=getPage();let variant='Basic';let codeTab='preview';let currentCode='';let previewWidth=390;
const $=s=>document.querySelector(s);const ui=()=>D[lang];const tr=()=>strings[lang];
function getPage(){return decodeURIComponent(location.hash.slice(1))||'overview'}
function titleOf(item){if(lang==='ko')return item.title;const map={'asset-overview':'Asset Overview',frame:'Asset Frames',asset:'Wrapped Assets','bottom-cta-overview':'BottomCTA Overview',dialog:'Dialog Overview','list-row-overview':'ListRow Overview','list-row-components':'ListRow Composition','list-row-legacy':'ListRow Legacy API','overlay-overview':'Overlay Extension'};return map[item.id]||item.title}
function descOf(item){if(item.description)return item.description[lang];return lang==='ko'?descriptions[item.id]||ui().tokenDesc:lang==='en'?`${titleOf(item)} for the Jejuyeora mobile app. Explore live examples, implementation code and the original API reference.`:`济州游啦移动应用的 ${titleOf(item)}。查看交互示例、实现代码与原文 API 参考。`}
const logo=icon('mountain',48);
function nav(){let html=`<a class="nav-link ${page==='overview'?'active':''}" href="#overview">${icon('grid',16)}${ui().overview}</a>`;for(const cat of ['foundation','component','utility']){const items=catalog.filter(i=>i.category===cat);html+=`<div class="nav-section">${ui()[cat]}<span>${items.length.toString().padStart(2,'0')}</span></div>`;let group='';for(const item of items){if(item.group&&item.group!==group){group=item.group;html+=`<div class="nav-group">${item.group==='OverlayExtension'?'Overlay Extension':item.group}</div>`}html+=`<a class="nav-link ${item.group?'child':''} ${page===item.id?'active':''}" href="#${item.id}" ${page===item.id?'aria-current="page"':''}>${item.group?'<span class="nav-dot"></span>':''}${titleOf(item)}</a>`}}return html}
function shell(){const sidebarScroll=$('.nav-scroll')?.scrollTop||0;const item=catalog.find(i=>i.id===page);const u=ui();$('#app').innerHTML=`<button class="mobile-scrim" aria-label="${u.close}" data-doc="nav-close"></button><aside class="docs-sidebar" id="docs-nav"><a class="docs-brand" href="#overview"><span class="brand-symbol">${logo}</span><span class="brand-word">${tr().brand}<span>DESIGN SYSTEM</span></span></a><nav class="nav-scroll" aria-label="${u.all}">${nav()}</nav><div class="sidebar-footer"><span class="status-dot"></span><span>v1.1.1 · MOBILE FIRST<br>Plander Designer ASEUL</span></div></aside><header class="docs-header"><button class="mode-button menu-toggle" aria-label="Menu" aria-controls="docs-nav" aria-expanded="false" data-doc="nav-open">${icon('menu')}</button><div class="crumb"><span>Design System</span>${icon('arrow',12)}<strong>${item?titleOf(item):u.overview}</strong></div><button class="header-search" data-doc="search" aria-label="${u.search}">${icon('search',16)}<span>${u.search}</span><kbd>/</kbd></button><div class="header-actions"><div class="locale-switch" aria-label="Language">${[['ko','KO'],['en','EN'],['zh','中文']].map(([l,s])=>`<button data-doc="lang" data-value="${l}" aria-pressed="${l===lang}">${s}</button>`).join('')}</div><button class="mode-button" data-doc="theme" aria-label="${u.scheme}" title="${u.scheme}">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon',18)}</button></div></header><main id="main" class="doc-main"><div class="page-content" id="content"></div></main><dialog class="search-dialog" aria-label="${u.search}"><div class="search-dialogheader">${icon('search',20)}<input id="doc-search" type="search" placeholder="${u.search}" aria-label="${u.search}" autocomplete="off"><button class="mode-button" aria-label="${u.close}" data-doc="search-close">${icon('close',18)}</button></div><div class="search-results"></div></dialog>`;renderPage();$('.nav-scroll').scrollTop=sidebarScroll;mountInteractions(document);}
function footer(){return `<footer class="doc-footer"><span>© Plander Designer ASEUL</span><span>JEJUYEORA · v1.1.1</span><a href="https://tossmini-docs.toss.im/tds-mobile/" target="_blank" rel="noopener">TDS Mobile ${icon('external',12)}</a><a href="https://designsystem.line.me/LDSG/foundation/overview-en/" target="_blank" rel="noopener">LINE Guide ${icon('external',12)}</a></footer>`}
function heading(title,desc,category,download=false){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${download?`<a class="download-link" href="./jejuyeora-dev-kit.zip" download>${icon('download',16)}${ui().download}</a>`:''}</div>`}
function section(title,desc=''){return `<div class="section-heading"><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`}
function overview(){const u=ui(),t=tr();return `${heading(u.title,u.intro,'MOBILE DESIGN SYSTEM',true)}<div class="overview-grid"><div class="overview-left"><div class="brand-card"><div class="brand-cardtop"><div class="brand-lockup">${logo}<strong>${t.brand}</strong></div></div><div class="brand-cardbottom"><div><strong>${u.brandTitle}</strong><p>${u.brandDesc}</p></div><span class="brand-color-hex">#634BFF</span></div></div><div class="spec-grid"><a class="spec-card" href="#typography">${icon('globe',22)}<div><h3>${u.font}</h3><p>${u.fontDesc}</p></div><span class="spec-value">Aa 가나다</span></a><button class="spec-card" data-doc="theme" style="text-align:left;color:var(--jy-text)">${icon('moon',22)}<div><h3>${u.theme}</h3><p>${u.themeDesc}</p></div><div class="jy-row"><span style="width:24px;height:24px;border-radius:50%;background:#161525;border:1px solid #77758b"></span><span style="width:24px;height:24px;border-radius:50%;background:#fff;border:1px solid #c9c7d6"></span><span class="jy-small jy-muted">Dark / Light</span></div></button><div class="spec-card">${icon('phone',22)}<div><h3>${u.mobile}</h3><p>${u.mobileDesc}</p></div><span class="spec-value">390<span style="font-size:13px;color:var(--jy-muted);letter-spacing:0"> px</span></span></div><a class="spec-card" href="#button">${icon('box',22)}<div><h3>${u.coverage}</h3><p>${u.coverageDesc}</p></div><span class="spec-value">83<span style="font-size:13px;color:var(--jy-muted);letter-spacing:0"> docs</span></span></a></div></div><div class="phone-stage"><div class="stage-label"><span>${u.phoneLabel.toUpperCase()}</span><span class="live-pill"><i class="status-dot"></i>LIVE PREVIEW</span></div><div class="phone"><div class="phone-status"><span>9:41</span><span class="phone-indicators">${icon('signal',14)}${icon('wifi',14)}${icon('battery',16)}</span></div><div class="phone-inner jy-demo" data-lang="${lang}"><div class="phone-apphead"><span class="tiny-label">JEJUYEORA</span><button class="jy-iconbtn" aria-label="${t.push}" data-action="toast" style="width:32px;height:32px">${icon('bell',20)}</button></div><h2>${u.sampleTitle.replace('\n','<br>')}</h2><label class="jy-search">${icon('search',16)}<input class="jy-input" aria-label="${t.search}" placeholder="${t.search}"></label><div class="jy-segment" role="tablist" aria-label="${t.explore}">${[t.all,t.place,t.food,t.stay].map((s,i)=>`<button role="tab" aria-selected="${i===0}" data-action="select-tab" tabindex="${i===0?0:-1}">${s}</button>`).join('')}</div><p hidden data-tab-result></p><div><div class="phone-sectiontitle">${t.place}<span>${t.more} ${icon('arrow',12)}</span></div><button class="jy-listrow" data-action="place"><span class="jy-asset">${icon('sun',24)}</span><span class="jy-rowtext"><strong>${t.seongsan}</strong><small>${t.east} · 4.9 ${icon('star',12)}</small></span>${Badge(t.popular)}</button><button class="jy-listrow" data-action="place"><span class="jy-asset" style="color:var(--jy-info);background:var(--jy-info-weak)">${icon('map',24)}</span><span class="jy-rowtext"><strong>${t.aewol}</strong><small>${t.west} · 4.8 ${icon('star',12)}</small></span>${icon('arrow',16)}</button></div>${Button(t.explore,{display:'block'})}</div><nav class="phone-nav" aria-label="App navigation">${[['home',u.navHome],['map',u.navMap],['heart',u.navSave],['user',u.navMy]].map(([ic,s],i)=>`<button class="${i===0?'active':''}" data-doc="phone-nav">${icon(ic,20)}${s}</button>`).join('')}</nav></div></div></div><div class="principle-bar"><span>${icon('check',14)}Dark first</span><span>8px spacing</span><span>16 / 24px radius</span><span>KO · EN · ZH</span><a href="./mobile-preview.html" class="reference-link">${icon('phone',14)}Mobile viewport ${icon('external',12)}</a></div>${section(u.start,u.structure)}<div class="foundation-strip">${[['colors','layers','Colors',u.colorsDesc],['typography','globe','Typography',u.typeDesc],['button','box',u.component,u.componentsDesc]].map(([id,ic,title,desc])=>`<a class="link-card" href="#${id}">${icon(ic,24)}<div><h3>${title}</h3><p>${desc}</p></div>${icon('arrow',16)}</a>`).join('')}</div>${footer()}`}
const palettes=designData.palettes;
function colorOn(hex){const c=hex.match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return c.reduce((a,x,i)=>a+x*[.2126,.7152,.0722][i],0)>.179?'#191525':'#fff'}
function semanticColors(){const u=ui();const style=getComputedStyle(document.documentElement);const toks=[['Primary','--jy-primary'],['Background','--jy-bg'],['Surface','--jy-surface'],['Elevated','--jy-elevated'],['Text / Primary','--jy-text'],['Text / Secondary','--jy-secondary'],['Text / Muted','--jy-muted'],['Border','--jy-border'],['Primary / Text','--jy-primary-text'],['Primary / Weak','--jy-primary-weak'],['Success','--jy-success'],['Danger','--jy-danger'],['Warning','--jy-warning'],['Info','--jy-info'],['Input','--jy-input'],['Overlay','--jy-overlay']];return `<div class="semantic-grid">${toks.map(([name,token])=>`<button class="color-tile" data-doc="copy" data-value="var(${token})"><div class="color-swatch" style="background:var(${token})"><span>${style.getPropertyValue(token).trim()}</span></div><div class="color-caption"><strong>${name}</strong><span>${token}</span></div></button>`).join('')}</div>`}
function colors(){const u=ui();const shades=[50,100,200,300,400,500,600,700,800,900];return `${heading('Colors',u.colorsDesc,'FOUNDATIONS',true)}${section(u.semantic,u.semanticDesc)}${semanticColors()}<div class="details-grid"><div class="detail-card"><h3>${icon('check',16)}${u.access}</h3><p>${u.accessFoundation}</p><div class="token-list" style="margin-top:16px"><div><span>#FFFFFF / #634BFF</span><code>5.28 : 1 · AA</code></div><div><span>#F5F4FC / #161525</span><code>16.46 : 1 · AAA</code></div></div></div><div class="detail-card"><h3>${icon('code',16)}${u.tokenUsage}</h3><p>${u.tokenDesc}</p><div class="code-area" style="margin-top:16px"><pre>.button {\n  background: var(--jy-primary);\n  color: var(--jy-on-primary);\n}</pre></div></div></div>${section(u.palette,u.paletteDesc)}<div class="foundation-panel palette-list">${Object.entries(palettes).map(([name,values])=>`<div class="palette-row"><h3>${name}${name==='Primary'?'<span>JEJUYEORA BRAND</span>':''}</h3><div class="palette-cells">${values.map((val,i)=>`<button class="palette-cell" data-doc="copy" data-value="var(--jy-${name.toLowerCase()}-${shades[i]})" style="background:#${val};color:${colorOn(val)}"><b>${shades[i]}</b><span>#${val.toUpperCase()}</span></button>`).join('')}</div></div>`).join('')}<div class="palette-row"><h3>Grey Opacity</h3><div class="palette-cells">${designData.opacity.map(([color,n],i)=>`<button class="palette-cell" data-doc="copy" data-value="var(--jy-grey-opacity-${shades[i]})" style="background:var(--jy-grey-opacity-${shades[i]});color:var(--jy-text)"><b>${shades[i]}</b><span>${n*100}%</span></button>`).join('')}</div></div></div>${section(u.spacing,u.spacingDesc)}<div class="foundation-panel"><div class="spacing-row">${[0,8,16,24,32,40,48,64].map(n=>`<div class="spacing-item"><i style="--space:${Math.max(1,n)}px"></i><span>${n}px</span></div>`).join('')}</div><div class="jy-row" style="margin-top:32px;gap:24px"><div class="jy-card" style="border:1px solid var(--jy-border);border-radius:16px">Radius 16</div><div class="jy-card" style="border:1px solid var(--jy-border)">Radius 24</div></div></div>${pager('colors')}${footer()}`}
function typography(){const u=ui(),t=tr();const scales=[['t1',30,40,700],['t2',26,35,700],['t3',22,31,700],['t4',20,29,600],['t5',17,25.5,600],['t6',15,22.5,500],['t7',13,19.5,500]];return `${heading('Typography',u.typeDesc,'FOUNDATIONS',true)}<div class="type-hero"><div class="tiny-label">PRETENDARD VARIABLE · NOTO SANS SC</div><div class="type-big">Aa 가나다<br><span lang="zh">你好，济州</span></div><div class="jy-small jy-muted">Regular 400 / Medium 500 / Semibold 600 / Bold 700</div></div>${section(u.typeScale,u.typeScaleDesc)}<div class="foundation-panel">${scales.map(([name,size,line,w])=>`<div class="type-sample"><code>${name} / ${size}px</code><p style="font-size:${size}px;line-height:${line/size};font-weight:${w};--type-size:${size}px">${t.trip}</p><span>${w} / ${line}</span></div>`).join('')}</div>${section(u.language,u.languageDesc)}<div class="font-preview-grid"><div class="font-preview" lang="ko"><h3>한국어 / Korean</h3><p>나만의 제주를<br>만나다</p><small>Pretendard Variable</small></div><div class="font-preview" lang="en"><h3>English</h3><p>Find your<br>own Jeju</p><small>Pretendard Variable</small></div><div class="font-preview" lang="zh"><h3>简体中文 / Chinese</h3><p>遇见属于<br>你的济州</p><small>Noto Sans SC</small></div></div><div class="details-grid"><div class="detail-card"><h3>${icon('globe',18)}${u.tokenUsage}</h3><div class="code-area"><pre>:root { --jy-font: Pretendard; }\n:lang(zh) {\n  --jy-font: 'Noto Sans SC';\n}\nbody { font-family: var(--jy-font); }</pre></div></div><div class="detail-card"><h3>${icon('phone',18)}${u.largeText}</h3><p>${u.largeDesc}</p></div></div>${typeReference()}${pager('typography')}${footer()}`}
function typeReference(){const u=ui();return `<details class="reference-details" open><summary><span>${u.sourceApi} · Typography</span><span class="ref-label">20 tokens</span></summary><p>${lang==='ko'?'TDS의 기본·보조 토큰과 iOS/Android 큰 글자 수치를 유지합니다. 11·12px 토큰은 원문 참조용이며 제주여라 앱 UI는 13px 이상을 사용합니다.':lang==='en'?'Original primary and sub typography tokens with iOS/Android accessibility scaling. The 11px and 12px tokens are reference values; Jejuyeora app UI uses 13px or larger.':'保留 TDS 基础与辅助字号，以及 iOS/Android 大字体数值。11px 与12px仅供原文参考，济州游啦界面使用13px以上。'}</p><div class="jy-row" style="gap:16px"><label class="jy-small">Platform <select class="jy-select" id="type-platform" style="min-height:40px;padding:8px"><option>Web</option><option>iOS</option><option>Android</option></select></label><label class="jy-small">Scale <select class="jy-select" id="type-scale" style="min-height:40px;padding:8px">${designData.iosScale.map(n=>`<option value="${n}">${n}%</option>`).join('')}</select></label><label class="jy-small">${u.weights}<select class="jy-select" id="type-weight" style="min-height:40px;padding:8px">${[300,400,500,600,700].map(n=>`<option ${n===600?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="table-scroll"><table class="api-table"><thead><tr><th>Token</th><th>Size / Line</th><th>${u.preview}</th></tr></thead><tbody>${designData.typography.map(t=>`<tr><td><code>${t.token}</code></td><td data-type-size="${t.token}">${t.size} / ${t.lineHeight}</td><td data-type-token="${t.token}" style="font-size:${t.size}px;line-height:${t.lineHeight/t.size};font-weight:600">${tr().trip}</td></tr>`).join('')}</tbody></table></div></details>`}
function updateType(){const platform=$('#type-platform').value;const scale=Number($('#type-scale').value);const weight=$('#type-weight').value;for(const t of designData.typography){const size=platform==='iOS'?t.ios[designData.iosScale.indexOf(scale)]:platform==='Android'?Math.min(t.androidMax,t.size*scale/100):t.size*scale/100;const el=$(`[data-type-token="${t.token}"]`);el.style.fontSize=size+'px';el.style.fontWeight=weight;$(`[data-type-size="${t.token}"]`).textContent=Number(size.toFixed(1))+' / '+Number((size*t.lineHeight/t.size).toFixed(1))}}
function codeFor(item){const id=item.id;const variantText=variant;const html=renderComponent(id,{lang,variant});if(codeTab==='html')return `<!-- Include tokens.css and jy-ui.css first. -->\n${html.replace(/></g,'>\n<')}`;if(codeTab==='css')return `@import './tokens.css';\n@import './jy-ui.css';\n@import './extensions.css';\n\n/* Tokens from tokens.css */\n:root {\n  --jy-primary: #634BFF;\n  --jy-bg: #161525;\n  --jy-radius-sm: 16px;\n  --jy-radius: 24px;\n  --jy-font: ${lang==='zh'?"'Noto Sans SC'":'Pretendard'};\n}\n\n/* The complete styles are provided by the imports above. */`;if(id.startsWith('use-')||id==='overlay-overview'){const fn=id==='use-toast'?'useToast':id==='use-bottom-sheet'?'useBottomSheet':'useDialog';const argument=fn==='useToast'?`'${tr().saved}'`:fn==='useBottomSheet'?`{ title: '${tr().select}',\n  options: ['${tr().east}', '${tr().west}'],\n  lang: '${lang}', onSelect: console.log }`:`{ title: '${tr().notice}',\n  description: '${tr().completeDesc}',\n  confirmLabel: '${tr().confirm}', lang: '${lang}' }`;return `import { ${fn} } from './components.js';\n\n${fn==='useDialog'?'const confirmed = await ':''}${fn}(${argument});`}
return `import { renderComponent, mountInteractions }\n  from './components.js';\n\nconst root = document.querySelector('#app');\nroot.innerHTML = renderComponent('${id}', {\n  lang: '${lang}',\n  variant: '${variantText}'\n});\nmountInteractions(root);`}
function renderBench(item){const u=ui();currentCode=codeFor(item);const body=codeTab==='preview'?`<div class="mobile-preview" style="width:${previewWidth}px"><div class="preview-status"><span>JEJUYEORA</span><span>${previewWidth} × AUTO</span></div>${renderComponent(item.id,{lang,variant})}</div>`:`<div class="code-area"><span class="code-label">${codeTab==='html'?item.id+'.html':codeTab==='css'?'tokens.css':item.id+'.js'}</span><button class="copy-code" data-doc="copy-code">${icon('copy',14)}Copy</button><pre><code>${esc(currentCode)}</code></pre></div>`;return `<div class="component-workbench"><div class="workbench-top"><div class="workbench-tabs" role="tablist" aria-label="Code preview">${[['preview',u.preview],['html','HTML'],['css','CSS'],['js','JS']].map(([key,label])=>`<button role="tab" aria-selected="${codeTab===key}" class="${codeTab===key?'active':''}" data-doc="code-tab" data-value="${key}">${label}</button>`).join('')}</div><div class="preview-actions"><select id="preview-width" aria-label="Preview width">${[320,360,375,390,414,540].map(w=>`<option value="${w}" ${previewWidth===w?'selected':''}>${w}px</option>`).join('')}</select><button data-doc="reset" aria-label="${u.reset}">${icon('phone',16)}</button></div></div><div class="workbench-body">${body}</div><div class="variantbar"><label>${u.variant}<select id="variant-select">${(examples[item.id]||item.examples||['Basic']).map(v=>`<option ${variant===v?'selected':''}>${v}</option>`).join('')}</select></label><span class="variant-count">${document.documentElement.dataset.theme==='dark'?'DARK':'LIGHT'} / ${lang.toUpperCase()}</span></div></div>`}
function component(item){const u=ui();const variants=examples[item.id]||item.examples||['Basic'];if(!variants.includes(variant))variant=variants[0];return `${heading(titleOf(item),descOf(item),item.category==='utility'?'UTILITIES / OVERLAY':`COMPONENTS${item.group?' / '+item.group.toUpperCase():''}`)}<div id="workbench">${renderBench(item)}</div><div class="details-grid"><div class="detail-card"><h3>${icon('code',16)}${u.usage}</h3><p>${u.devDesc}</p><div class="token-list" style="margin-top:16px"><div><span>HTML / CSS / JavaScript</span><code>ES modules</code></div><div><span>${u.states}</span><code>${variants.length} examples</code></div><div><span>${u.previewNote}</span><code>320–540px</code></div></div></div><div class="detail-card"><h3>${icon('phone',16)}${u.access}</h3><p>${u.accessDesc}</p></div></div>${item.api.length?`<details class="reference-details"><summary><span>${u.sourceApi}</span><span class="ref-label">TDS ${icon('down',14)}</span></summary><p>${u.sourceNote}</p>${item.api.map(a=>`<div class="table-scroll"><table class="api-table"><caption>${esc(a.title)}</caption><thead><tr><th>${u.apiName}</th><th>${u.apiType}</th><th>${u.apiDefault}</th></tr></thead><tbody>${a.items.map(p=>`<tr><td><code>${esc(p.name)}${p.required?' *':''}</code></td><td><code>${esc((Array.isArray(p.type)?p.type:[p.type]).join(' | '))}</code></td><td>${esc(p.defaultValue)}</td></tr>`).join('')}</tbody></table></div>`).join('')}</details>`:''}${item.variants.length?`<details class="reference-details"><summary><span>${u.reference}</span><span class="ref-label">${item.variants.length} ${icon('down',14)}</span></summary><p>${u.referenceDesc}</p><div class="jy-row">${item.variants.map(v=>`<span class="jy-badge">${v}</span>`).join('')}</div></details>`:''}<p class="source-note">${u.sourceDate} · <a class="reference-link" href="${item.source}" target="_blank" rel="noopener">${item.origin==='line'?(lang==='ko'?'LINE 가이드 보기':lang==='zh'?'查看 LINE 指南':'View LINE guide'):u.source} ${icon('external',13)}</a></p>${pager(item.id)}${footer()}`}
function pager(id){const i=catalog.findIndex(x=>x.id===id);const p=catalog[i-1],n=catalog[i+1];return `<nav class="pager" aria-label="Page navigation">${p?`<a href="#${p.id}">${icon('back',16)}<span><small>${ui().previous}</small>${titleOf(p)}</span></a>`:''}${n?`<a href="#${n.id}"><span><small>${ui().next}</small>${titleOf(n)}</span>${icon('arrow',16)}</a>`:''}</nav>`}
function renderPage(){const item=catalog.find(i=>i.id===page);$('#content').innerHTML=page==='overview'?overview():page==='colors'?colors():page==='typography'?typography():item?.category==='foundation'?renderFoundation(item,{lang,ui:ui(),t:tr(),heading,section,pager,footer,audit:referenceAudit}):item?component(item):overview();document.title=`${item?titleOf(item):ui().overview} — ${tr().brand} Design System`;}
function refreshBench(){const item=catalog.find(i=>i.id===page);if(item){$('#workbench').innerHTML=renderBench(item);mountInteractions(document)}}
async function copy(s){try{await navigator.clipboard.writeText(s);useToast(ui().copied)}catch{const ta=document.createElement('textarea');ta.value=s;document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();useToast(ui().copied)}}
function searchResults(query=''){const q=query.trim().toLowerCase();const matches=catalog.filter(i=>[i.title,i.id,i.group,i.category,descriptions[i.id],ui()[i.category]].join(' ').toLowerCase().includes(q));$('.search-results').innerHTML=matches.length?matches.map(i=>`<a class="search-result" href="#${i.id}" data-doc="search-result">${icon(i.category==='foundation'?'layers':i.category==='utility'?'code':'box',20)}<div><strong>${titleOf(i)}</strong><small>${ui()[i.category]}${i.group?' / '+i.group:''}</small></div>${icon('arrow',16)}</a>`).join(''):`<div class="search-empty">${ui().noresult}</div>`}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').tabIndex=-1;$('#main').focus();return}const b=e.target.closest('[data-doc]');if(!b)return;const a=b.dataset.doc;if(a==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('jy-theme',document.documentElement.dataset.theme);shell()}if(a==='lang'){lang=b.dataset.value;document.documentElement.lang=lang;localStorage.setItem('jy-lang',lang);shell()}if(a==='nav-open'){document.body.classList.add('nav-open');b.setAttribute('aria-expanded','true');$('.nav-link.active')?.focus()}if(a==='nav-close'){document.body.classList.remove('nav-open');$('[data-doc=nav-open]').setAttribute('aria-expanded','false');$('[data-doc=nav-open]').focus()}if(a==='code-tab'){codeTab=b.dataset.value;refreshBench()}if(a==='copy-code')copy(currentCode);if(a==='copy')copy(b.dataset.value);if(a==='reset')refreshBench();if(a==='search'){const dlg=$('.search-dialog');dlg.showModal();searchResults();$('#doc-search').focus()}if(a==='search-close'||a==='search-result')$('.search-dialog').close();if(a==='phone-nav'){b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));useToast(b.textContent.trim())}});
document.addEventListener('change',e=>{if(e.target.id==='layout-width'){const w=Number(e.target.value);$('#layout-device').style.width=w+'px';$('#layout-device .layout-columns').style.paddingInline=(w<360?16:24)+'px';$('#layout-metrics').textContent=w+'px · 4 cols · '+(w<360?16:24)+'px margin · 16px gutter'}if(e.target.id==='preview-width'){previewWidth=Number(e.target.value);refreshBench()}if(['type-platform','type-scale','type-weight'].includes(e.target.id))updateType();if(e.target.id==='variant-select'){variant=e.target.value;refreshBench()}});
document.addEventListener('input',e=>{if(e.target.id==='doc-search')searchResults(e.target.value)});
document.addEventListener('keydown',e=>{if((e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))||((e.metaKey||e.ctrlKey)&&e.key==='k')){e.preventDefault();$('[data-doc=search]').click()}if(e.key==='Escape'){document.body.classList.remove('nav-open');$('[data-doc=nav-open]').setAttribute('aria-expanded','false')}});
window.addEventListener('hashchange',()=>{page=getPage();variant='Basic';codeTab='preview';document.body.classList.remove('nav-open');shell();window.scrollTo({top:0});$('#main').setAttribute('tabindex','-1');$('#main').focus({preventScroll:true})});
shell();
